// InventoryServiceHandler is an implementation of the meurpg.characters.v1.InventoryService
// service.
type InventoryServiceHandler interface {
	// GetInventory returns the character's inventory. The master reads any
	// character's (an NPC's included); a player only their own (a pending member their
	// own pending one). For a player, an unidentified item shows only its look.
	GetInventory(context.Context, *connect.Request[v1.GetInventoryRequest]) (*connect.Response[v1.GetInventoryResponse], error)
	// ListItemCatalog returns what can be given: the SRD equipment and, to the master only,
	// the 362 magic items, with their Portuguese names, categories, rarities,
	// attunement, the bases and options a generic one asks for and how much the engine
	// applies of each. A player gets the equipment alone.
	ListItemCatalog(context.Context, *connect.Request[v1.ListItemCatalogRequest]) (*connect.Response[v1.ListItemCatalogResponse], error)
	// GiveItems adds items to a character's inventory, up to 20 grants at once. The
	// master gives anything to any character with a full sheet. A player gives
	// themselves free-text lines and SRD equipment (never a magic item, never
	// unidentified) while the sheet is a draft, as they filled the equipment before;
	// after the first session starts it is `permission_denied`. An item that stacks
	// (equipment, ammunition, potions, scrolls of the same kind and look) joins the
	// line it matches.
	//
	// Errors: `invalid_argument` for a key that does not exist, a family without its
	// variant, a base or an option the item does not take, a scroll without a spell or
	// with a spell of another level; `failed_precondition` ITEM_BLOCKED_REASON_FULL.
	GiveItems(context.Context, *connect.Request[v1.GiveItemsRequest]) (*connect.Response[v1.GiveItemsResponse], error)
	// SetEquipped wears or wields an item, or takes it off. The slot must be free
	// (SRD 5.1 "Multiple Items of the Same Kind": one suit of armor, one pair of boots,
	// one pair of gloves, one pair of bracers, one item of headwear, one cloak, plus an
	// amulet, a belt and two rings; weapons and wands are held without limit). Body
	// armor is not changed in combat (donning takes minutes): the master may.
	// Idempotent: setting what it already is changes nothing.
	//
	// Errors: ITEM_BLOCKED_REASON_NOT_EQUIPPABLE, SLOT_TAKEN (with the item in the
	// way), IN_COMBAT.
	SetEquipped(context.Context, *connect.Request[v1.SetEquippedRequest]) (*connect.Response[v1.SetEquippedResponse], error)
	// RemoveItem takes an item, or some of its quantity, out of the inventory. The master
	// always; the owner while the sheet is a draft.
	RemoveItem(context.Context, *connect.Request[v1.RemoveItemRequest]) (*connect.Response[v1.RemoveItemResponse], error)
	// TransferItem hands an item, or some of its quantity, to another character: the owner
	// gives their own to another player's living character of the campaign; the master moves
	// any item between any two characters with a full sheet. The item arrives
	// not equipped and not attuned (SRD 5.1: attunement ends when another creature attunes,
	// and a magic item changes hands), and an unidentified item stays unidentified. The
	// session history records it for the master (ListItemLog).
	TransferItem(context.Context, *connect.Request[v1.TransferItemRequest]) (*connect.Response[v1.TransferItemResponse], error)
	// AdjustCoins adds the given coins to the character's purse, or takes them away
	// (negative numbers), never below zero. The master and the owner.
	//
	// Errors: ITEM_BLOCKED_REASON_NOT_ENOUGH when a coin would fall below zero.
	AdjustCoins(context.Context, *connect.Request[v1.AdjustCoinsRequest]) (*connect.Response[v1.AdjustCoinsResponse], error)
	// RequestItemRest is the owner's mark, for the master's next short rest, that the
	// character will spend it focused on an item (SRD 5.1 "Attunement", "Identifying a Magic
	// Item"): to attune to it, to end the attunement or to learn what it is. It only marks:
	// the master's short rest does it (ConfirmItemRests), or the master answers one item with
	// ResolveItemRest. Outside combat. For an identified item the request is checked at
	// once (an item that needs no attunement, a fourth item, a restriction not met...); for an
	// unidentified one it is taken as it is, so the answer does not reveal the item.
	RequestItemRest(context.Context, *connect.Request[v1.RequestItemRestRequest]) (*connect.Response[v1.RequestItemRestResponse], error)
	// ResolveItemRest is the master's answer to one request, or the master doing it directly
	// (a kind with no request waiting). Approving attunes, ends the attunement or identifies,
	// under the same rules (three items, the restriction, no other copy, outside
	// combat); attuning also identifies the item. Refusing clears the request.
	//
	// Errors: ITEM_BLOCKED_REASON_NOTHING_TO_ANSWER when the item has no such request and no
	// kind was given.
	ResolveItemRest(context.Context, *connect.Request[v1.ResolveItemRestRequest]) (*connect.Response[v1.ResolveItemRestResponse], error)
	// UseItem drinks a potion: a potion of healing rolls its dice and heals (never above
	// the maximum), a potion of heroism gives its temporary hit points. The owner and the
	// master, out of combat; in a combat the potion is an action and goes through
	// CombatService.UseItem (ITEM_BLOCKED_REASON_USE_IN_COMBAT). A scroll or a wand's spell
	// is cast through the spell flow (CAST_IT). Uses up one potion. A potion with dice needs
	// `roll_in_app` or `typed_sum`, and the campaign dice setting binds a player here as on
	// every roll.
	UseItem(context.Context, *connect.Request[v1.UseItemRequest]) (*connect.Response[v1.UseItemResponse], error)
	// SpendCharges spends charges of an item (SRD 5.1 "Charges"), for a property that stays a
	// reminder: the table resolves it. The owner and the master.
	//
	// Errors: ITEM_BLOCKED_REASON_NOT_ENOUGH (with how many are left).
	SpendCharges(context.Context, *connect.Request[v1.SpendChargesRequest]) (*connect.Response[v1.SpendChargesResponse], error)
	// ConfirmItemRests is the master's short rest for the items: every attunement, end of
	// attunement and identification the players marked (RequestItemRest) on the characters
	// given, or on all of the campaign's when none is, is done at once, under the rules of
	// ResolveItemRest. What cannot be done (a fourth item, a restriction not met, a cursed
	// item) stays marked and comes back in `blocked`. The short rest of the party
	// (resources and hit dice) calls the same code in the same transaction, so the item part
	// never happens without the rest. Master only; refused with IN_COMBAT in a combat.
	ConfirmItemRests(context.Context, *connect.Request[v1.ConfirmItemRestsRequest]) (*connect.Response[v1.ConfirmItemRestsResponse], error)
	// ListItemRests lists what the players marked for the next short rest (attunements, ends of
	// attunement and identifications), with the names as the master knows the items, the count of
	// attunements before and after and the refusal each would get now. It is the items' part of
	// the short rest's preview. Master only.
	ListItemRests(context.Context, *connect.Request[v1.ListItemRestsRequest]) (*connect.Response[v1.ListItemRestsResponse], error)
	// RegainCharges is dawn for the items: every item with charges that regains them
	// rolls the dice its description gives and gets that many back (never above the
	// maximum). One character, or all the characters of the campaign when
	// character_id is empty. Master only.
	RegainCharges(context.Context, *connect.Request[v1.RegainChargesRequest]) (*connect.Response[v1.RegainChargesResponse], error)
	// SetCoins sets the character's purse to the given coins, the owner's or the master's edit
	// ("Editar moedas"); each coin 0 to 1,000,000.
	SetCoins(context.Context, *connect.Request[v1.SetCoinsRequest]) (*connect.Response[v1.SetCoinsResponse], error)
	// UseScroll reads a spell scroll outside a combat (SRD 5.1 "Spell Scroll"): the spell must be
	// on the reader's class list, otherwise ITEM_BLOCKED_REASON_SCROLL_UNREADABLE and the scroll
	// stays; a spell of a level above the reader's highest spell slot takes an ability check with
	// the spellcasting ability, DC 10 + the spell's level, rolled with `roll` (a failure loses the
	// spell, the scroll is spent either way). The result says the spell, the save DC and attack
	// bonus the scroll gives (13/+5 to 19/+11 by level) and the check. In a combat the reading is
	// an action and goes through CombatService.UseItem. Casting the spell's effects is the spell
	// flow's: the result names what was cast.
	UseScroll(context.Context, *connect.Request[v1.UseScrollRequest]) (*connect.Response[v1.UseScrollResponse], error)
	// RecoverAmmunition gives back pieces of a stack of ammunition after a battle (SRD 5.1
	// "Ammunition": a minute of searching recovers half of what was expended): up to half of the
	// pieces spent since the last recovery, rounded down (the app's rule, the SRD does not say
	// how). The spent count restarts afterwards. The owner and the master, outside a combat.
	//
	// Errors: ITEM_BLOCKED_REASON_NOTHING_SPENT, NOT_ENOUGH (with the most that can be recovered).
	RecoverAmmunition(context.Context, *connect.Request[v1.RecoverAmmunitionRequest]) (*connect.Response[v1.RecoverAmmunitionResponse], error)
	// PreviewTextToItems reads a free-text line of the inventory ("Corda de cânhamo (15 m), 10
	// rações, tochas") and proposes the items it holds, matched against the SRD equipment by
	// their Portuguese names. It changes nothing. A piece with no number in the text comes back
	// with a guess (10 for a plural, 1 otherwise) flagged `quantity_guessed`, for the player to
	// correct; a piece that matches no equipment is proposed as free text.
	PreviewTextToItems(context.Context, *connect.Request[v1.PreviewTextToItemsRequest]) (*connect.Response[v1.PreviewTextToItemsResponse], error)
	// ConfirmTextToItems replaces the free-text line with the lines the owner confirmed (the
	// proposals, with the quantities corrected). The original text is kept
	// (InventoryView.converted_texts). The owner and the master.
	ConfirmTextToItems(context.Context, *connect.Request[v1.ConfirmTextToItemsRequest]) (*connect.Response[v1.ConfirmTextToItemsResponse], error)
	// UpdateItem is the master's correction of a line: its quantity, charges, look,
	// scroll spell or whether it is identified. Fields not set stay as they are.
	UpdateItem(context.Context, *connect.Request[v1.UpdateItemRequest]) (*connect.Response[v1.UpdateItemResponse], error)
	// ListItemLog returns what the inventories went through in the open session, newest
	// first: items given, handed over, attuned, used and recharged. The master reads every line
	// with the items as they are (a line says "Uma espada com runas" when it was given and "era
	// Espada longa +1" when it was identified). A player reads only the lines about their own
	// characters (given to them, handed over by them or to them, used by them), with each item
	// named as the character sees it: the look of an item that is still unidentified, never
	// its name.
	ListItemLog(context.Context, *connect.Request[v1.ListItemLogRequest]) (*connect.Response[v1.ListItemLogResponse], error)
}

